CREATE FUNCTION nmv_cli_executor_indeterminate_removed_release_valid(e jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE AS $$
DECLARE p jsonb:=e->'plan'; r jsonb:=e->'receipt'; q jsonb:=p->'request'; b jsonb:=r->'closureBoundary';
  first_zero jsonb:=b->'observations'->0; last_zero jsonb:=b->'observations'->1; x jsonb; o jsonb; before_run jsonb; die jsonb; m jsonb; i integer; t text;
BEGIN
  IF NOT nmv_cli_executor_indeterminate_removed_shape_valid(e,$shape$__EVIDENCE_SHAPE__$shape$::jsonb) THEN RETURN false; END IF;
  IF e->'requestId' IS DISTINCT FROM q->'requestId' OR e->'owner' IS DISTINCT FROM q->'owner' OR e->'dispatchAt' IS DISTINCT FROM q->'dispatchAt'
    OR e->'bindingHash' IS DISTINCT FROM q->'bindingHash' OR e->'reference' IS DISTINCT FROM p->'reviewReference'
    OR e->'notBefore' IS DISTINCT FROM r->'observedAt' OR r->>'planHash' IS DISTINCT FROM encode(sha256(convert_to(nmv_boundary_canonical(p),'UTF8')),'hex')
    OR p->'executor' IS DISTINCT FROM r->'executor' OR p->'topology' IS DISTINCT FROM r->'topology'
    OR p->'executor'->>'baseUrlHash' IS DISTINCT FROM encode(sha256(convert_to(p->'executor'->>'baseUrl','UTF8')),'hex')
    OR q->'provider' IS DISTINCT FROM q->'transport'->'provider' OR q->'model' IS DISTINCT FROM q->'transport'->'model'
    OR q->'chargedTokens' IS DISTINCT FROM q->'totalTokenBound' THEN RETURN false; END IF;
  FOREACH t IN ARRAY ARRAY[e->>'dispatchAt',e->>'notBefore',e->>'evaluatedAt',p->>'createdAt',r->>'observedAt',p->'interval'->>'beforeNativeAt',b->>'stopAttemptAt'] LOOP
    IF to_char(t::timestamptz AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')<>t THEN RETURN false; END IF;
  END LOOP;
  t:=p->'control'->>'updatedAt';
  IF to_char(t::timestamptz AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')<>t THEN RETURN false; END IF;
  IF (p->'interval'->>'beforeNativeAt')::timestamptz >= (q->>'dispatchAt')::timestamptz
    OR (p->>'createdAt')::timestamptz < (q->>'dispatchAt')::timestamptz OR t::timestamptz > (p->>'createdAt')::timestamptz
    OR (e->>'evaluatedAt')::timestamptz < (r->>'observedAt')::timestamptz OR (r->>'observedAt')::timestamptz < (p->>'createdAt')::timestamptz
    OR (e->>'evaluatedAt')::timestamptz-(p->>'createdAt')::timestamptz>interval '30 minutes'
    OR (e->>'evaluatedAt')::timestamptz-(r->>'observedAt')::timestamptz>interval '5 minutes'
    OR jsonb_array_length(r->'exits')<>jsonb_array_length(p->'candidates')
    OR (b->>'stopAttemptAt')::timestamptz<(q->>'dispatchAt')::timestamptz OR (b->>'stopAttemptAt')::timestamptz>(first_zero->>'observedAt')::timestamptz
    OR (first_zero->>'observedAt')::timestamptz<(p->>'createdAt')::timestamptz OR (first_zero->>'observedAt')::timestamptz>=(last_zero->>'observedAt')::timestamptz
    OR last_zero->'observedAt' IS DISTINCT FROM r->'observedAt'
    OR (e->>'evaluatedAt')::timestamptz-(first_zero->>'observedAt')::timestamptz>interval '5 minutes'
    OR first_zero->'captureArtifactHash'=last_zero->'captureArtifactHash' OR first_zero->'inventoryArtifactHash'=last_zero->'inventoryArtifactHash'
    OR last_zero->'exits' IS DISTINCT FROM r->'exits' OR last_zero->'wholeService' IS DISTINCT FROM r->'wholeService' THEN RETURN false; END IF;
  IF (SELECT count(DISTINCT a->>'taskId') FROM jsonb_array_elements(p->'candidates') a)<>jsonb_array_length(p->'candidates')
    OR (SELECT count(DISTINCT a->>'containerId') FROM jsonb_array_elements(p->'candidates') a)<>jsonb_array_length(p->'candidates')
    OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p->'candidates') a WHERE a->>'taskId'=p->'interval'->>'singleTaskId') THEN RETURN false; END IF;
  IF r->'wholeService'->'endpointClosed'->>'kind'='trusted_forwarder_no_backend'
    AND r->'wholeService'->'endpointClosed'->'backendServiceId' IS DISTINCT FROM p->'executor'->'serviceId' THEN RETURN false; END IF;
  FOR i IN 0..jsonb_array_length(p->'candidates')-1 LOOP
    x:=r->'exits'->i; before_run:=x->'originalBefore';die:=x->'dockerDie';
    IF x->'identity' IS DISTINCT FROM p->'candidates'->i OR x->'identity'->'serviceId' IS DISTINCT FROM p->'executor'->'serviceId'
      OR x->'identity'->'nodeId' IS DISTINCT FROM p->'executor'->'nodeId'
      OR before_run->'identity' IS DISTINCT FROM x->'identity' OR before_run->'executor' IS DISTINCT FROM p->'executor'
      OR before_run->'topology' IS DISTINCT FROM p->'topology' OR (before_run->>'observedAt')::timestamptz<(q->>'dispatchAt')::timestamptz
      OR (before_run->>'observedAt')::timestamptz>(b->>'stopAttemptAt')::timestamptz
      OR die->'containerId' IS DISTINCT FROM x->'identity'->'containerId' OR die->'taskId' IS DISTINCT FROM x->'identity'->'taskId'
      OR die->'serviceId' IS DISTINCT FROM x->'identity'->'serviceId' OR die->'nodeId' IS DISTINCT FROM x->'identity'->'nodeId'
      OR die->'daemonId' IS DISTINCT FROM p->'executor'->'daemonId' OR die->'daemonBootId' IS DISTINCT FROM p->'executor'->'daemonBootId'
      OR die->'exitCode' IS DISTINCT FROM x->'exitCode'
      OR floor((die->>'timeNano')::numeric/1000000) IS DISTINCT FROM extract(epoch FROM (die->>'occurredAt')::timestamptz)*1000
      OR (die->>'occurredAt')::timestamptz<(b->>'stopAttemptAt')::timestamptz OR (die->>'occurredAt')::timestamptz>(first_zero->>'observedAt')::timestamptz THEN RETURN false; END IF;
    t:=before_run->>'observedAt';IF to_char(t::timestamptz AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')<>t THEN RETURN false; END IF;
    t:=die->>'occurredAt';IF to_char(t::timestamptz AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')<>t THEN RETURN false; END IF;
    IF first_zero->'missing'->i->'task'->'artifactHash'=last_zero->'missing'->i->'task'->'artifactHash'
      OR first_zero->'missing'->i->'container'->'artifactHash'=last_zero->'missing'->i->'container'->'artifactHash' THEN RETURN false; END IF;
  END LOOP;
  FOR o IN SELECT * FROM jsonb_array_elements(b->'observations') LOOP
    t:=o->>'observedAt';
    IF to_char(t::timestamptz AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')<>t
      OR o->'executor' IS DISTINCT FROM p->'executor' OR o->'topology' IS DISTINCT FROM p->'topology'
      OR o->'control' IS DISTINCT FROM p->'control' OR o->'writer' IS DISTINCT FROM p->'writer' OR o->'exits' IS DISTINCT FROM r->'exits'
      OR jsonb_array_length(o->'missing')<>jsonb_array_length(p->'candidates')
      OR o->'wholeService'->'endpointClosed'->>'kind'='trusted_forwarder_no_backend'
        AND o->'wholeService'->'endpointClosed'->'backendServiceId' IS DISTINCT FROM p->'executor'->'serviceId' THEN RETURN false; END IF;
    FOR i IN 0..jsonb_array_length(p->'candidates')-1 LOOP
      m:=o->'missing'->i;
      IF m->'identity' IS DISTINCT FROM p->'candidates'->i OR m->'task'->'observedAt' IS DISTINCT FROM o->'observedAt'
        OR m->'container'->'observedAt' IS DISTINCT FROM o->'observedAt' THEN RETURN false; END IF;
    END LOOP;
  END LOOP;
  RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;
