-- Snapshot the COMPLETE0136 predecessor with the actual indeterminate state; never project evidence to dispatched.
DO $$
DECLARE predicates text; amount integer;
BEGIN
  SELECT string_agg('('||substring(pg_get_constraintdef(oid) FROM 7)||')',' AND ' ORDER BY conname),count(*) INTO predicates,amount
    FROM pg_constraint WHERE conrelid='model_capacity_requests'::regclass AND conname=ANY(ARRAY['model_capacity_requests_logical_check','model_capacity_requests_members_check','model_capacity_requests_dispatch_check','model_capacity_requests_terminal_check']);
  IF amount<>4 THEN RAISE EXCEPTION 'cli_executor_indeterminate_predecessor_missing'; END IF;
  EXECUTE 'CREATE FUNCTION nmv_cli_executor_indeterminate_removed_predecessor_valid(v jsonb) RETURNS boolean LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $fn$ SELECT coalesce(('||predicates||'),false) FROM jsonb_populate_record(NULL::model_capacity_requests,v||''{"state":"indeterminate","terminal_evidence":null,"terminal_evidence_hash":null,"settled_at":null}''::jsonb) model_capacity_requests $fn$';
END $$;
