CREATE FUNCTION nmv_cli_executor_indeterminate_removed_transition_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE c model_capacity_control; f dr_writer_fence; observed_now timestamptz;
BEGIN
  IF TG_OP='UPDATE' AND OLD.terminal_evidence->>'kind'='cli_executor_indeterminate_removed_boundary_exit' THEN
    IF NEW IS NOT DISTINCT FROM OLD THEN RETURN NEW; END IF;
    RAISE EXCEPTION 'cli_executor_terminal_immutable';
  END IF;
  IF NEW.terminal_evidence->>'kind' IS DISTINCT FROM 'cli_executor_indeterminate_removed_boundary_exit' THEN RETURN NEW; END IF;
  IF TG_OP<>'UPDATE' THEN RAISE EXCEPTION 'cli_executor_transition_invalid'; END IF;
  SELECT * INTO STRICT f FROM dr_writer_fence WHERE id=1 FOR SHARE;
  SELECT * INTO STRICT c FROM model_capacity_control WHERE id=1 FOR UPDATE;
  observed_now:=clock_timestamp();
  IF f.state<>'active' OR c.mode<>'draining' OR OLD.state<>'indeterminate' OR NEW.state<>'withdrawn' OR OLD.terminal_evidence IS NOT NULL OR OLD.terminal_evidence_hash IS NOT NULL OR OLD.settled_at IS NOT NULL
    OR NEW.terminal_evidence->'plan'->'request'->>'rowHash' IS DISTINCT FROM encode(sha256(convert_to(to_jsonb(OLD)::text,'UTF8')),'hex')
    OR (to_jsonb(OLD)-ARRAY['state','terminal_evidence','terminal_evidence_hash','updated_at']) IS DISTINCT FROM (to_jsonb(NEW)-ARRAY['state','terminal_evidence','terminal_evidence_hash','updated_at'])
    OR NEW.terminal_evidence->'plan'->'writer' IS DISTINCT FROM jsonb_build_object('lineageId',f.lineage_id,'writerEpoch',f.writer_epoch)
    OR NEW.terminal_evidence->'plan'->'control' IS DISTINCT FROM jsonb_build_object('mode',c.mode,'epoch',c.epoch,'revision',c.revision,'policyHash',c.policy_hash,'updatedAt',to_char(c.updated_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))
    OR (NEW.terminal_evidence->>'evaluatedAt')::timestamptz NOT BETWEEN observed_now-interval '30 seconds' AND observed_now
    OR (NEW.terminal_evidence->'receipt'->>'observedAt')::timestamptz NOT BETWEEN observed_now-interval '5 minutes' AND observed_now
    OR (NEW.terminal_evidence->'receipt'->'closureBoundary'->'observations'->0->>'observedAt')::timestamptz NOT BETWEEN observed_now-interval '5 minutes' AND observed_now
    OR (NEW.terminal_evidence->'plan'->>'createdAt')::timestamptz NOT BETWEEN observed_now-interval '30 minutes' AND observed_now
    THEN RAISE EXCEPTION 'cli_executor_transition_conflict'; END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
CREATE TRIGGER model_capacity_cli_executor_indeterminate_removed_guard BEFORE INSERT OR UPDATE ON model_capacity_requests FOR EACH ROW EXECUTE FUNCTION nmv_cli_executor_indeterminate_removed_transition_guard();
